approved_command_preview:
$ErrorActionPreference = 'Stop'
$repo = [Environment]::GetEnvironmentVariable('DCOIR_REPO_ROOT','Machine')
$expected = '9189b0a9f45a55bfff0fd1cbff7d438356643f0f'
git -C $repo fetch origin issue-484-lane-separation-scoring
$actual = (git -C $repo rev-parse origin/issue-484-lane-separation-scoring).Trim()
if ($actual -ne $expected) { throw "PR #501 head drifted: expected $expected got $actual" }
$worktree = Join-Path $env:RUNNER_TEMP 'pr501-copilot-fix-validation'
if (Test-Path $worktree) { Remove-Item -Recurse -Force $worktree }
git -C $repo worktree add --detach $worktree $expected
try {
  $tools = Join-Path $worktree 'project_sources\gemini\tools'
  Set-Location $tools
  python -m py_compile lib\gemini_behavioral_replay_scoring.py validate_gemini_lane_separation_scoring.py
  python validate_gemini_lane_separation_scoring.py
  python run_gemini_behavioral_replay_validation_suite.py
  $status = git -C $worktree status --porcelain
  if ($status) { throw "Validation mutated detached worktree: $status" }
} finally {
  Set-Location $repo
  git -C $repo worktree remove --force $worktree
}
Write-Host 'PR #501 Copilot-fix exact-head validation passed.'

